fn insert(
    oline: &Vec<char>,
    l: usize,
    nl: &Vec<char>,
    p: usize,
    at_pos: usize
) -> Vec<char> {
    // Preconditions
    assert!(l <= oline.len(), "l must not exceed the length of the first sequence");
    assert!(p <= nl.len(), "p must not exceed the length of the second sequence");
    assert!(at_pos <= l, "at_pos must be between 0 and l (inclusive)");

    // Allocate result with exact needed capacity
    let mut result = Vec::with_capacity(l + p);

    // 1) Copy the first `at_pos` characters from the first sequence
    result.extend(&oline[..at_pos]);

    // 2) Insert the first `p` characters from the second sequence
    result.extend(&nl[..p]);

    // 3) Copy the remaining characters from the first sequence,
    //    i.e., from `at_pos` up to `l`
    result.extend(&oline[at_pos..l]);

    result
}

