        let a: Vec<char> = "abcdef".chars().collect();
        let b: Vec<char> = "XYZ".chars().collect();

        // Insert "XYZ" at position 3 in "abcdef" (considering l=6, p=3)
        let res = insert(&a, 6, &b, 3, 3);
        let s: String = res.into_iter().collect();
        assert_eq!(&s, "abcXYZdef");
