        // Insert at start (at_pos = 0)
        let r1 = insert(&a, 5, &b, 5, 0);
        assert_eq!(r1.into_iter().collect::<String>(), "WORLDhello");

        // Insert at end (at_pos = l)
        let r2 = insert(&a, 5, &b, 5, 5);
        assert_eq!(r2.into_iter().collect::<String>(), "helloWORLD");
