        let a: Vec<char> = "rust".chars().collect();
        let b: Vec<char> = "lang".chars().collect();

        // p = 0 (no insertion)
        let r1 = insert(&a, 4, &b, 0, 2);
        assert_eq!(r1.into_iter().collect::<String>(), "rust");

        // l = 0 (nothing from first, just prefix of second)
        let r2 = insert(&a, 0, &b, 3, 0);
        assert_eq!(r2.into_iter().collect::<String>(), "lan");
